#!/usr/bin/env node
/**
 * Preflight for local Android builds.
 *
 * The NDK toolchain bakes its own absolute path into the linker invocation and
 * does not quote it. On a Windows account whose profile contains a space —
 * `C:\Users\MTECH COMPUTERS\AppData\Local\Android\Sdk` — the path splits and
 * the link step fails with ~80 undefined C++ symbols. The error names missing
 * symbols, so it reads as a broken dependency or a bad RN version; the cause is
 * the space, and it costs hours to find.
 *
 * This cannot be fixed in the repo: `android/` is generated by prebuild and
 * gitignored, and `local.properties` is written from ANDROID_HOME at build
 * time. So the durable fix is to fail here, before the build, naming the cause
 * and the remedy — rather than let the linker fail in a way that hides both.
 *
 * Not fatal on non-Windows: the quoting problem is specific to the Windows
 * toolchain, and CI/macOS builds should not be blocked by a check for it.
 */

import { existsSync } from 'node:fs';
import path from 'node:path';

const RESET = '\u001b[0m';
const RED = '\u001b[31m';
const YELLOW = '\u001b[33m';

function sdkPath() {
  const fromEnv = process.env.ANDROID_HOME ?? process.env.ANDROID_SDK_ROOT;
  if (fromEnv) return { dir: fromEnv, source: process.env.ANDROID_HOME ? 'ANDROID_HOME' : 'ANDROID_SDK_ROOT' };
  const local = process.env.LOCALAPPDATA;
  if (local) return { dir: path.join(local, 'Android', 'Sdk'), source: 'default location' };
  return null;
}

const sdk = sdkPath();

if (!sdk) {
  console.error(`${YELLOW}Android SDK location unknown — set ANDROID_HOME.${RESET}`);
  process.exit(1);
}

if (!existsSync(sdk.dir)) {
  console.error(`${YELLOW}Android SDK not found at ${sdk.dir} (${sdk.source}).${RESET}`);
  console.error('Install it via Android Studio, or point ANDROID_HOME at an existing SDK.');
  process.exit(1);
}

if (process.platform === 'win32' && /\s/.test(sdk.dir)) {
  console.error(`${RED}The Android SDK path contains a space:${RESET}`);
  console.error(`  ${sdk.dir}   (from ${sdk.source})`);
  console.error('');
  console.error('The NDK linker does not quote this path, so the build fails partway');
  console.error('through with dozens of undefined C++ symbols — an error that points');
  console.error('nowhere near the real cause.');
  console.error('');
  console.error('Fix (run once, in an elevated prompt):');
  console.error(String.raw`  mklink /J C:\AndroidSdk` + ` "${sdk.dir}"`);
  console.error(String.raw`  setx ANDROID_HOME C:\AndroidSdk`);
  console.error('');
  console.error('Then open a new terminal so ANDROID_HOME is picked up, delete');
  console.error('mobile/android/ and re-run, so local.properties is regenerated.');
  process.exit(1);
}

console.log(`Android SDK: ${sdk.dir}`);
